import{_ as a,o as e,c as i,ag as t}from"./chunks/framework.DFlFRONG.js";const k=JSON.parse('{"title":"TeamOne Proxy Server Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"proxy-server/troubleshooting.md","filePath":"proxy-server/troubleshooting.md"}'),n={name:"proxy-server/troubleshooting.md"};function l(h,s,p,o,r,c){return e(),i("div",null,[...s[0]||(s[0]=[t(`<h1 id="teamone-proxy-server-troubleshooting" tabindex="-1">TeamOne Proxy Server Troubleshooting <a class="header-anchor" href="#teamone-proxy-server-troubleshooting" aria-label="Permalink to &quot;TeamOne Proxy Server Troubleshooting&quot;">​</a></h1><p>Use the checks below if the TeamOne Proxy Server is not starting, is not reachable, or cannot connect to IBM Planning Analytics / TM1.</p><p>For questions or assistance, contact <strong><a href="mailto:teamone@succeedium.com" target="_blank" rel="noreferrer">teamone@succeedium.com</a></strong>.</p><h2 id="confirm-the-docker-containers-are-running" tabindex="-1">Confirm the Docker Containers Are Running <a class="header-anchor" href="#confirm-the-docker-containers-are-running" aria-label="Permalink to &quot;Confirm the Docker Containers Are Running&quot;">​</a></h2><p>Run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ps</span></span></code></pre></div><p>Both the <code>teamone</code> and <code>nginx</code> containers should be running.</p><h2 id="check-the-nginx-logs" tabindex="-1">Check the Nginx Logs <a class="header-anchor" href="#check-the-nginx-logs" aria-label="Permalink to &quot;Check the Nginx Logs&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tail=200</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nginx</span></span></code></pre></div><p>Use this to investigate:</p><ul><li>Nginx startup errors</li><li>configuration errors</li><li>certificate loading errors</li><li>HTTP / HTTPS listener issues</li></ul><h2 id="check-the-teamone-application-logs" tabindex="-1">Check the TeamOne Application Logs <a class="header-anchor" href="#check-the-teamone-application-logs" aria-label="Permalink to &quot;Check the TeamOne Application Logs&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tail=200</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> teamone</span></span></code></pre></div><p>Use this to investigate:</p><ul><li>application startup errors</li><li>request handling errors</li><li>proxy errors</li><li>connectivity issues to IBM Planning Analytics / TM1</li></ul><h2 id="test-the-teamone-application-backend" tabindex="-1">Test the TeamOne Application Backend <a class="header-anchor" href="#test-the-teamone-application-backend" aria-label="Permalink to &quot;Test the TeamOne Application Backend&quot;">​</a></h2><p>The TeamOne application listens internally on port <code>8000</code>.</p><p>Run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8000/</span></span></code></pre></div><p>A JSON response confirms that the TeamOne application backend is running.</p><h2 id="load-balancer-ssl-deployments" tabindex="-1">Load Balancer SSL Deployments <a class="header-anchor" href="#load-balancer-ssl-deployments" aria-label="Permalink to &quot;Load Balancer SSL Deployments&quot;">​</a></h2><p>For deployments where SSL/TLS is managed by a load balancer, Nginx receives HTTP traffic from the load balancer.</p><p>The default TeamOne Proxy Server HTTP listener port is <code>80</code>.</p><p>Test locally:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost/</span></span></code></pre></div><p>If this succeeds locally but the external TeamOne URL does not work, review the load balancer target, listener, routing, and network access rules.</p><p>The expected traffic flow is:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User Browser</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>HTTPS / TLS 443</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Customer Load Balancer</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>HTTP 80</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>TeamOne Proxy Server</span></span></code></pre></div><p>Confirm that the load balancer forwards traffic to the correct TeamOne Proxy Server host and port.</p><h2 id="direct-ssl-deployments" tabindex="-1">Direct SSL Deployments <a class="header-anchor" href="#direct-ssl-deployments" aria-label="Permalink to &quot;Direct SSL Deployments&quot;">​</a></h2><p>For deployments where the SSL/TLS certificate is installed directly on the TeamOne Proxy Server, Nginx listens for HTTPS traffic.</p><p>The default HTTPS listener port is <code>443</code>.</p><p>Test locally:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -vk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://localhost/</span></span></code></pre></div><p>A successful response confirms that Nginx is accepting HTTPS connections.</p><h2 id="confirm-the-active-nginx-configuration" tabindex="-1">Confirm the Active Nginx Configuration <a class="header-anchor" href="#confirm-the-active-nginx-configuration" aria-label="Permalink to &quot;Confirm the Active Nginx Configuration&quot;">​</a></h2><p>Run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -it</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nginx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nginx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -T</span></span></code></pre></div><p>For load balancer SSL deployments, confirm that the HTTP listener is configured.</p><p>For direct SSL deployments, confirm that SSL certificate directives are present:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -it</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nginx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nginx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -T</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ssl_certificate</span></span></code></pre></div><h2 id="direct-ssl-confirm-certificate-files" tabindex="-1">Direct SSL: Confirm Certificate Files <a class="header-anchor" href="#direct-ssl-confirm-certificate-files" aria-label="Permalink to &quot;Direct SSL: Confirm Certificate Files&quot;">​</a></h2><p>If SSL/TLS is managed directly by the TeamOne Proxy Server, confirm the certificate and key exist inside the Nginx container:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -it</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nginx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ls</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -l</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/nginx/certs</span></span></code></pre></div><p>The expected files are:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>teamone.crt</span></span>
<span class="line"><span>teamone.key</span></span></code></pre></div><h2 id="direct-ssl-validate-the-certificate-and-private-key" tabindex="-1">Direct SSL: Validate the Certificate and Private Key <a class="header-anchor" href="#direct-ssl-validate-the-certificate-and-private-key" aria-label="Permalink to &quot;Direct SSL: Validate the Certificate and Private Key&quot;">​</a></h2><p>From the <code>teamone-server-distr</code> directory, run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> x509</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -in</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cert/teamone.crt</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -text</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -noout</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rsa</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -in</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cert/teamone.key</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -check</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -noout</span></span></code></pre></div><p>To confirm that the certificate and private key match:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> x509</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -noout</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -modulus</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -in</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cert/teamone.crt</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> md5</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rsa</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -noout</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -modulus</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -in</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cert/teamone.key</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> md5</span></span></code></pre></div><p>The two hashes should match.</p><h2 id="verify-the-teamone-proxy-url" tabindex="-1">Verify the TeamOne Proxy URL <a class="header-anchor" href="#verify-the-teamone-proxy-url" aria-label="Permalink to &quot;Verify the TeamOne Proxy URL&quot;">​</a></h2><p>Open:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://&lt;teamone-proxy-fqdn&gt;</span></span></code></pre></div><p>Confirm that it displays:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TeamOne is up!</span></span></code></pre></div><p>If the browser reports a certificate warning, confirm that the certificate used by the load balancer or TeamOne Proxy Server is trusted by the user&#39;s device and browser.</p><h2 id="test-ibm-planning-analytics-tm1-connectivity" tabindex="-1">Test IBM Planning Analytics / TM1 Connectivity <a class="header-anchor" href="#test-ibm-planning-analytics-tm1-connectivity" aria-label="Permalink to &quot;Test IBM Planning Analytics / TM1 Connectivity&quot;">​</a></h2><p>Use the TeamOne Proxy Server to request the TM1 REST API metadata endpoint.</p><p>Example using HTTPS for the TM1 connection:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://&lt;teamone-proxy-fqdn&gt;/?url=https://&lt;tm1-host&gt;:&lt;tm1-rest-api-port&gt;/api/v1/$metadata</span></span></code></pre></div><p>Example using HTTP for the TM1 connection:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://&lt;teamone-proxy-fqdn&gt;/?url=http://&lt;tm1-host&gt;:&lt;tm1-rest-api-port&gt;/api/v1/$metadata</span></span></code></pre></div><p>If the TeamOne Proxy Server itself is reachable but the TM1 request fails, check:</p><ul><li>the TM1 hostname</li><li>the TM1 REST API port</li><li>whether TM1 uses HTTP or HTTPS</li><li>outbound firewall or security group rules</li><li><code>PROXY_ALLOWED_HOST_PATTERN</code></li><li>DNS resolution from the TeamOne Proxy Server</li><li>IBM Planning Analytics / TM1 availability</li></ul><h2 id="check-allowed-host-configuration" tabindex="-1">Check Allowed Host Configuration <a class="header-anchor" href="#check-allowed-host-configuration" aria-label="Permalink to &quot;Check Allowed Host Configuration&quot;">​</a></h2><p>Review:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>teamone-server-distr/config/.env</span></span></code></pre></div><p>Confirm that the required TM1 host is included in:</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">PROXY_ALLOWED_HOST_PATTERN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span></span></code></pre></div><p>If Cognos SSO is used, confirm that the Cognos Gateway host is included in:</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">PROXY_OAUTH_ALLOWED_HOST_PATTERN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span></span></code></pre></div><p>After changing <code>.env</code>, recreate the containers:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> teamone-server-distr/docker-compose.yml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force-recreate</span></span></code></pre></div><h2 id="recreate-the-containers" tabindex="-1">Recreate the Containers <a class="header-anchor" href="#recreate-the-containers" aria-label="Permalink to &quot;Recreate the Containers&quot;">​</a></h2><p>If configuration changes are not being applied or one of the containers is in an unexpected state, recreate them:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> teamone-server-distr/docker-compose.yml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> down</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> teamone-server-distr/docker-compose.yml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><p>Then confirm:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ps</span></span></code></pre></div><h2 id="related-documentation" tabindex="-1">Related Documentation <a class="header-anchor" href="#related-documentation" aria-label="Permalink to &quot;Related Documentation&quot;">​</a></h2><ul><li><a href="./index.html">About TeamOne Proxy Server</a></li><li><a href="./configuration.html">TeamOne Proxy Server Configuration</a></li><li><a href="./installation-load-balancer-ssl.html">Installation Guide – SSL Managed by Load Balancer</a></li><li><a href="./installation-direct-ssl.html">Installation Guide – SSL Managed by TeamOne Proxy Server</a></li><li><a href="./upgrade-load-balancer-ssl.html">Upgrade Guide – SSL Managed by Load Balancer</a></li><li><a href="./upgrade-direct-ssl.html">Upgrade Guide – SSL Managed by TeamOne Proxy Server</a></li></ul>`,82)])])}const g=a(n,[["render",l]]);export{k as __pageData,g as default};
